// Generated by tools/tracking-plan.mjs from docs/telemetry/tracking-plan.json.
// Do not edit: change the plan and run the script.

/**
 * Every event the frontends emit, by name, with its attributes (ADR 0036).
 *
 * An event that is not in the tracking plan does not compile. Each one carries
 * the question it answers and the decision its value would change.
 */
export interface TrackedEvents {
  /**
   * A browser agent called one of the shop's WebMCP tools. Emitted with actor `webmcp`.
   *
   * WebMCP: Do browser agents use the shop's WebMCP tools, which ones, and do they succeed?
   * Decides: Which tools to keep, extend or drop; a high share of refusals means a tool's contract is wrong for an agent.
   */
  readonly webmcp_tool_invoked: {
    /** The tool's registered name; never its arguments. */
    readonly tool: string;
    /** Refused is the shop saying no; failed is the tool breaking. */
    readonly outcome: 'answered' | 'refused' | 'failed';
  };

  /**
   * A shopper opened a product page. Only with analytics consent.
   *
   * Product page: How do shoppers reach a product — a search, a category, the home page — and how many product views does a cart follow?
   * Decides: Where discovery work goes: the search box, the taxonomy or the home page's rows.
   */
  readonly product_viewed: {
    /** The page before this one, by kind; direct when there was none in this tab. */
    readonly arrived_from: 'search' | 'category' | 'home' | 'other' | 'direct';
  };

  /**
   * A shopper opened a category listing (R-0 of the redesign). Only with analytics consent.
   *
   * Browsing by category: Do people browse the taxonomy, or go straight to search?
   * Decides: Whether the category pages earn their place in the navigation.
   */
  readonly category_opened: {
    /** How the shopper got there: menu once the storefront has one (R-5), otherwise the kind of page before this one; direct when there was none in this tab. The kind and never the URL. */
    readonly arrived_from: 'menu' | 'search' | 'category' | 'home' | 'other' | 'direct';
  };

  /**
   * A shopper opened the words behind a spec — the quote and its support. Only with analytics consent.
   *
   * Specs with their source: Do shoppers open the sentence behind a spec, and do they compare products side by side once they can?
   * Decides: If nobody opens a source, the chip is decoration: keep the table, drop the chip's weight and spend review effort elsewhere. If comparisons are made and followed by a cart, the typed half of claims is worth its model and the next source (manuals, datasheets) is worth adding; if they are not, the comparison goes back to being a nice-to-have.
   */
  readonly spec_source_opened: {
    /** Where the value came from; only a value an approved claim put there has words to open. */
    readonly source: 'description';
  };

  /**
   * A shopper opened a side-by-side comparison. Only with analytics consent.
   *
   * Specs with their source: Do shoppers open the sentence behind a spec, and do they compare products side by side once they can?
   * Decides: If nobody opens a source, the chip is decoration: keep the table, drop the chip's weight and spend review effort elsewhere. If comparisons are made and followed by a cart, the typed half of claims is worth its model and the next source (manuals, datasheets) is worth adding; if they are not, the comparison goes back to being a nice-to-have.
   */
  readonly products_compared: {
    /** How many products were compared, two to four. */
    readonly products: number;
  };

  /**
   * The shopkeeper opened a backoffice screen (R-0 of the redesign). A staff event: sent by default under the shop's notice to staff, and never with who they are.
   *
   * Backoffice jobs: Does the shopkeeper finish their jobs — publish, review a claim, ship, decide a return, suspend an agent — and how long does each take from opening its screen?
   * Decides: A job whose time does not fall after the redesign goes back to R-3; a job that is refused more than it is done points at a screen that invites the wrong action. The before and after are the redesign article's evidence.
   */
  readonly backoffice_view_opened: {
    /** The screen, by its route; never an id in it. */
    readonly view: 'dashboard' | 'review' | 'catalogue' | 'claims' | 'attributes' | 'search' | 'promotions' | 'stock' | 'orders' | 'returns' | 'agents' | 'audit' | 'variants';
  };

  /**
   * The shopkeeper did what a screen is for — published, approved, shipped, decided, suspended — and how the server answered (R-0). A staff event.
   *
   * Backoffice jobs: Does the shopkeeper finish their jobs — publish, review a claim, ship, decide a return, suspend an agent — and how long does each take from opening its screen?
   * Decides: A job whose time does not fall after the redesign goes back to R-3; a job that is refused more than it is done points at a screen that invites the wrong action. The before and after are the redesign article's evidence.
   *
   * Palette and list shortcuts: Does anybody reach screens and records through the palette, or move down a queue with j and k, and does the pane get used rather than the row?
   * Decides: R-6 keeps the shortcuts only if they are used (R-2, P11); a palette nobody opens after a month is simplified to screens alone; a pane nobody acts from goes back to the drawing board in R-3.
   */
  readonly backoffice_action_taken: {
    /** The screen it was done on. */
    readonly view: 'dashboard' | 'review' | 'catalogue' | 'claims' | 'attributes' | 'search' | 'promotions' | 'stock' | 'orders' | 'returns' | 'agents' | 'audit' | 'variants';
    /** What was done, from a closed list. */
    readonly action: 'publish' | 'withdraw' | 'import' | 'claim_approve' | 'claim_reject' | 'order_ship' | 'order_deliver' | 'order_cancel' | 'return_approve' | 'return_reject' | 'return_receive' | 'return_refund' | 'agent_register' | 'agent_trust' | 'agent_suspend' | 'agent_reinstate';
    /** done; refused when the server said no (a 4xx, a rule); failed when it could not answer. */
    readonly outcome: 'done' | 'refused' | 'failed';
    /** Where it was pressed: on the list's row, in the pane beside it, or as the page's own action (R-3's adoption signal for the pane). */
    readonly via: 'row' | 'pane' | 'page';
  };

  /**
   * A staff member chose light, dark or the system's theme in the account menu (the redesign's R-3). A staff event under the shop's notice (ADR 0041), never with who they are.
   *
   * Theme choice: Does anybody change the theme from the system's, and to which?
   * Decides: If nobody changes it within a month of the laboratory's use, the switch goes and the system's preference stays (the redesign's R-3). The storefront's half arrives with R-5.1 as a behavioural event.
   */
  readonly backoffice_theme_chosen: {
    /** What was chosen, not what the system resolved it to. */
    readonly theme: 'system' | 'light' | 'dark';
  };

  /**
   * A staff member reached something through the command palette or a list shortcut rather than by pointing (the redesign's R-4.6). A staff event under the shop's notice (ADR 0041), never with who they are.
   *
   * Palette and list shortcuts: Does anybody reach screens and records through the palette, or move down a queue with j and k, and does the pane get used rather than the row?
   * Decides: R-6 keeps the shortcuts only if they are used (R-2, P11); a palette nobody opens after a month is simplified to screens alone; a pane nobody acts from goes back to the drawing board in R-3.
   */
  readonly backoffice_affordance_used: {
    /** The palette (Ctrl K or /), or j and k down a queue. */
    readonly affordance: 'palette' | 'keys';
    /** What it reached; never which one. */
    readonly target: 'screen' | 'order' | 'product' | 'agent' | 'next' | 'previous';
  };

  /**
   * A shopper chose light, dark or the system's theme (the redesign's R-5.1). Behavioural, so it waits for analytics consent.
   *
   * Storefront theme choice: Do shoppers change the theme from their system's, and does the dark shop hold the same conversion?
   * Decides: If nobody changes it in a month, the switch goes and the system's preference stays; if the dark shop converts worse, its product imagery is looked at before anything else.
   */
  readonly theme_chosen: {
    /** What was chosen, not what the system resolved it to. */
    readonly theme: 'system' | 'light' | 'dark';
  };
}

/**
 * Which events wait for analytics consent. A behavioural event says what a
 * person did and is dropped until they agree; a technical one is not; a staff
 * one is the shop measuring its own tools under a notice to staff, sent unless
 * the staff member switched it off (ADR 0041).
 */
export const TRACKED_EVENT_CONSENT: Readonly<Record<keyof TrackedEvents, 'behavioural' | 'technical' | 'staff'>> = {
  webmcp_tool_invoked: 'behavioural',
  product_viewed: 'behavioural',
  category_opened: 'behavioural',
  spec_source_opened: 'behavioural',
  products_compared: 'behavioural',
  backoffice_view_opened: 'staff',
  backoffice_action_taken: 'staff',
  backoffice_theme_chosen: 'staff',
  backoffice_affordance_used: 'staff',
  theme_chosen: 'behavioural',
};
